async(page)=>{
const vocabulary={suitcase:"maleta",book:"libro",house:"casa",cat:"gato",dog:"perro",mom:"mamá",dad:"papá",milk:"leche",water:"agua"};
const events=[];
for(let i=0;i<20;i++){
 const next=page.getByRole('button',{name:/^(Check|Continue)$/}).last(); await next.waitFor();
 const radios=page.getByRole('radio'); let active=null;
 for(let j=0;j<await radios.count();j++){const r=radios.nth(j);if(await r.isVisible()&&await r.isEnabled()){active=r;break;}}
 const before=await page.locator('body').ariaSnapshot();
 if(!active){events.push({stop:"no enabled radios; model inspection required",before});break;}
 const challenge=active.locator('xpath=ancestor::*[starts-with(@data-test,"challenge ")][1]');
 const heading=await challenge.getByRole('heading',{level:1}).innerText();
 const word=heading.match(/[“"]([^”"]+)[”"]/); const answer=word&&vocabulary[word[1]];
 if(!answer){events.push({stop:"unknown question",heading,before});break;}
 const option=challenge.getByRole('radio',{name:new RegExp("^"+answer+" \\d+$")});
 if(await option.count()!==1){events.push({stop:"answer mapping not uniquely visible",heading,answer,before});break;}
 await option.click(); await page.getByRole('button',{name:'Check',exact:true}).click();
 await page.getByRole('button',{name:'Continue',exact:true}).last().waitFor();
 const feedback=await page.locator('body').ariaSnapshot();
 events.push({heading,answer,before,feedback});
 if(/Correct solution:|Incorrect/.test(feedback)){events.push({stop:"unexpected wrong answer; retain failure"});break;}
 await page.getByRole('button',{name:'Continue',exact:true}).last().click();
 await challenge.waitFor({state:'hidden',timeout:10000});
}
return {url:page.url(),events,final:await page.locator('body').ariaSnapshot()};
}
